pub(crate) fn verify(packet: Packet) -> Result<Self> {
    let h = &packet.header;
    let work = pon_work::verify(h.challenge(), h.work_task, h.target, &packet.proof)
        .map_err(|e| Error::from(format!("WORK:{e:?}")))?;
    Ok(Self {
        packet,
        work,
        owner_permit: None,
    })
}

pub(crate) fn verify_with_progress(
    packet: Packet,
    progress: &mut impl FnMut(pon_work::VerificationProgress) -> Result<()>,
) -> Result<Self> {
    let h = &packet.header;
    let work = pon_work::verify_with_progress(
        h.challenge(),
        h.work_task,
        h.target,
        &packet.proof,
        progress,
    )
    .map_err(|error| match error {
        pon_work::VerificationError::Relation(error) => Error::from(format!("WORK:{error:?}")),
        pon_work::VerificationError::Cancelled(error) => error,
    })?;
    Ok(Self {
        packet,
        work,
        owner_permit: None,
    })
}

pub(crate) fn verify_with_arithmetic_facts(
    packet: Packet,
    facts: &pon_work::arithmetic_facts::ArithmeticFactCache,
    progress: &mut impl FnMut(pon_work::VerificationProgress) -> Result<()>,
    observation: &mut pon_work::arithmetic_facts::ArithmeticObservation,
) -> Result<Self> {
    let h = &packet.header;
    let work = facts
        .verify_with_observation(
            h.challenge(),
            h.work_task,
            h.target,
            &packet.proof,
            progress,
            observation,
        )
        .map_err(|error| match error {
            pon_work::arithmetic_facts::FactError::Relation(error) => {
                Error::from(format!("WORK:{error:?}"))
            }
            pon_work::arithmetic_facts::FactError::Cancelled(error) => error,
            pon_work::arithmetic_facts::FactError::Unavailable => {
                Error::from("WORK_ARITHMETIC_FACTS_UNAVAILABLE")
            }
        })?;
    Ok(Self {
        packet,
        work,
        owner_permit: None,
    })
}

fn key(challenge: Hash, task: Hash, target: Hash, bytes: &[u8]) -> Option<Hash> {
    // The original verifier refuses a wrong width before reading proof
    // bytes. An optional cache must not turn that constant-cost refusal
    // into an unbounded hash over an attacker-controlled buffer.
    if bytes.len() != PROOF_BYTES {
        return None;
    }
    #[cfg(test)]
    CACHE_KEY_PROOF_BYTES.with(|count| count.set(count.get() + bytes.len()));
    Some(hash(
        b"w1-exact-invalid-math-v1",
        &[PROFILE.as_bytes(), &challenge, &task, &target, bytes],
    ))
}

pub fn encode(&self) -> Vec<u8> {
    let mut o = Vec::with_capacity(HEADER_BYTES);
    o.extend(b"PNH1");
    o.extend(1_u16.to_le_bytes());
    for h in [self.network, self.parameters, self.parent] {
        o.extend(h)
    }
    o.extend(self.height.to_le_bytes());
    o.extend(self.timestamp.to_le_bytes());
    for h in [
        self.target,
        self.miner,
        self.transactions,
        self.state,
        self.receipts,
        self.work_task,
    ] {
        o.extend(h)
    }
    o.extend(self.nonce.to_le_bytes());
    o
}
